  ('checker',          'Checker',          'Validates and redeems vouchers on-site.',                                 true, 5),
  ('support',          'Support',          'Read access across the workspace to assist users.',                       true, 6),
  ('analyst',          'Read-only Analyst','Views and exports analytics only.',                                       true, 7)
